import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables validation - invalid schema argument
 * Should fail: Second argument must be params.flowVariables
 */
export const setFlowVariablesInvalidSchema = Flow(
    {
        $id: Now.ID['set-flow-variables-invalid-schema'],
        name: 'SetFlowVariables Invalid Schema Test',
        description: 'Test SetFlowVariables validation with invalid schema argument',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            status: StringColumn({
                label: 'Status',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-invalid-schema-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // This should fail validation: wrong schema argument (should be params.flowVariables, not params.trigger)
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-invalid-schema-instance'],
                annotation: 'Invalid: wrong schema argument',
            },
            params.trigger as any, // Invalid: should be params.flowVariables
            {
                status: 'active',
            }
        )
    }
)
